  "basis": {
    "A": {
      "facts": ["S01", "S02", "S12"],
      "rules": [
        "lending-2020-12第13条、第31条",
        "civil-code-2020第157条、第682条"
      ],
      "explanation": "A于2022年成立，适用现行套取金融机构贷款转贷无效规则，不以高利转贷或借款人知情为要件，不能套用lending-2015第14条的旧要件。返还范围限于实际取得财产，已返还20261元全部抵扣；同交易号收据不构成另一笔交付。丁不负有效保证合同项下的给付责任。",
      "calculation": "143089.00－20261.00＝122828.00元；不计未交付的票面差额及未请求的赔偿。"
    },
    "B本息": {
      "facts": ["S03", "S04", "S05", "S13"],
      "rules": [
        "civil-code-2020第670条、第679条、第680条",
        "lending-2020-12第25条、第26条、第27条、第28条"
      ],
      "explanation": "合法自有资金借贷有效。预扣利息不计本金，初始本金为198783－12493＝186290元。归档无新增交付、无债务更新，不能直接采用虚增的纸面本金或重置合同成立时LPR。13.2%低于3.70%×4＝14.8%，依约逐期计入合法利息，并另受最初本金全期间单利总额上限约束。逾期部分依借期内利率计算。",
      "calculation": "相邻结算日及截日的日数为175、103、84、204，共566日。逐期结果＝186290×(1＋13.2%×175/365)×(1＋13.2%×103/365)×(1＋13.2%×84/365)×(1＋13.2%×204/365)，展示取分为227317.84元；全期间上限＝186290×(1＋14.8%×566/365)，展示取分为229043.81元。取较小值后抵扣SP-01的25000元，最终余额202317.84元。计算过程中不逐期取分。"
    },
    "B保证": {
      "facts": ["S06", "S12"],
      "rules": [
        "civil-code-2020第688条、第691条、第692条、第693条、第695条",
        "guarantee-2020第13条、第25条、第29条、第31条、第32条"
      ],
      "explanation": "戊承诺无条件清偿、无需先向乙追索，且共同正文明确戊庚各对全部B债务承担连带责任保证，不能因无类型标题认定为一般保证。两人均同意原合法结息机制。保证期间写至本息还清属于约定不明；未经两人书面同意的展期不改变保证期间，均从原到期日2023-01-12起六个月，至2023-07-12届满。戊案虽于7月9日撤诉，但完整诉状已于7月7日送达，期间内行权有效；庚于7月6日独立收到完整给付请求，也属期间内有效行权，并非借用对戊行权的效力。7月18日催告不是挽救逾期行权的依据。内部各50%的约定只规范相互追偿，不使对外全额保证变成按份保证；庚的保证未消灭，戊不存在第29条所称追偿权丧失，二人的相关免责主张均不成立。"
    },
    "C利率与付款认定": {
      "facts": ["S07", "S08", "S09", "S11"],
      "rules": [
        "lending-2015第26条",
        "lending-2020-12第25条、第28条、第31条",
        "civil-code-2020第560条、第561条"
      ],
      "explanation": "C自有资金借贷有效。按甲明确请求，成立日至2020-08-19按23.5%计算，未超过旧规则24%的保护标准；自2020-08-20起按题设起诉时LPR的四倍，即13%计算，包括逾期期间。2022年保证文件不是新借款，不能重置借款日期。费用、利息、本金的顺序源于2019年双方原始约定；仅T-02有有效补充协议改为本金优先，其26952元全部抵本金。其他付款的乙单方本金备注不能变更双方约定。T-01截图、收据与主表是同一交易，只计一次；X-01已撤销且未到账，乙点击提交不构成清偿。利息仅按未偿本金实际日数/365单利计算，未付利息不复利。"
    },
    "C计算": {
      "facts": ["S07", "S08", "S09", "S13", "S14"],
      "method": "各段起日计息、止日不计息，付款当日不再对被偿还本金计息。日数依次为70、127、175、188＋32、202、421、395、26；其中T-03至T-04分为2020-08-20之前188日按23.5%、之后32日按13%。保留中间精度，下列流水余额仅为展示取分。",
      "payment_balances": [
        {
          "transaction": "T-01",
          "principal_after": "213658.20",
          "interest_after": "0.00",
          "expenses_after": "0.00",
          "allocation": "25221元先清费用1680元，再清70日利息，余款抵本金。"
        },
        {
          "transaction": "T-02",
          "principal_after": "186706.20",
          "interest_after": "17470.22",
          "expenses_after": "0.00",
          "allocation": "26952元全部抵本金，此前127日利息留存。"
        },
        {
          "transaction": "T-03",
          "principal_after": "186706.20",
          "interest_after": "9823.63",
          "expenses_after": "0.00",
          "allocation": "28683元不足清偿累计合法利息，不抵本金。"
        },
        {
          "transaction": "T-04",
          "principal_after": "186706.20",
          "interest_after": "4136.69",
          "expenses_after": "0.00",
          "allocation": "30414元不足清偿累计合法利息，不抵本金。"
        },
        {
          "transaction": "T-05",
          "principal_after": "172130.51",
          "interest_after": "0.00",
          "expenses_after": "0.00",
          "allocation": "32145元先清累计利息，余款抵本金。"
        },
        {
          "transaction": "T-06",
          "principal_after": "164064.65",
          "interest_after": "0.00",
          "expenses_after": "0.00",
          "allocation": "33876元先清421日利息，余款抵本金。"
        },
        {
          "transaction": "T-07",
          "principal_after": "151539.07",
          "interest_after": "0.00",
          "expenses_after": "0.00",
          "allocation": "35607元先清395日利息，余款抵本金。"
        }
      ],
      "final_calculation": "T-07后未取分本金约151539.074820元；至2023-08-01前再计26日利息：未取分本金×13%×26/365，约1403.293350元。SP-01不抵C，之后亦无付款。各项分别取分后C合计＝151539.07＋1403.29＋0.00＝152942.36元。"
    },
    "C保证": {
      "facts": ["S07", "S10", "S12", "S14"],
      "rules": [
        "civil-code-2020第687条、第691条、第692条、第693条、第697条、第1260条",
        "guarantee-2020第25条、第31条、第34条"
      ],
      "explanation": "己的保证于2022年成立，应适用当时保证规则，不随2019年借款适用旧保证规则。正文明确乙不能履行、无力偿还时才代偿，构成一般保证。未约定保证期间，从2022-12-15到期起六个月，至2023-06-15届满。5月8日仅催告己不能替代对乙起诉；6月8日起诉虽于6月12日撤回，但6月14日已在期间届满前重新对乙有效起诉，故保证责任存续，己的消灭抗辩不成立。6月25日仅确认收件且否认付款义务，不成立新保证，也不是维持原保证责任的依据。案件尚未审判、执行，乙有可执行财产，且无先诉抗辩例外或放弃，故甲要求己立即支付不能支持。辛的债务加入不减免原保证范围。"
    },
    "SP-01抵充": {
      "facts": ["S06", "S10", "S13", "S14"],
      "rules": [
        "civil-code-2020第560条、第561条"
      ],
      "explanation": "09:20到账的25000元依双方约定仅用于B、C，不用于A。付款时B、C均已到期，戊、庚的全额保证及己的全额一般保证均依法存续，保证人资信、担保履行能力和价值不存在争议；己享有先诉抗辩不等于C无担保。满足SP附件约定条件，应比较可强制请求的年利率：B为13.2%，C为13%，而非C纸面23.5%或B的14.8%法定上限。因此全部25000元抵B。13:40辛才签署债务加入文件，不能追溯改变09:20已完成的抵充，乙的相反主张不成立。"
    },
    "辛": {
      "facts": ["S12", "S14"],
      "rules": [
        "civil-code-2020第552条、第697条",
        "guarantee-2020第36条"
      ],
      "explanation": "《代偿支持》正文明确辛与乙一并负担SP-01后C债务的50%，甲可单独请求辛，不以先追索乙或乙无力偿还为条件，且不免除乙义务，属于明确的债务加入，不适用含义不明时推定保证的分支。没有新交付、债务更新或实际清偿，不改变C原借款日期、计息规则及未偿总额。甲已于当日请求辛付款，辛没有一般保证的先诉抗辩，可以在承诺范围内立即请求给付。甲所称仅凭标题、不问正文即应立即付款的普遍主张错误，但本案正文确实支持限额内立即付款。",
      "calculation": "依共同条款先将C本金、利息、费用各自取分再合计，辛的范围＝152942.36×50%＝76471.18元；其余76471.18元不属于辛的承诺范围。"
    },
    "总额及责任重叠": {
      "facts": ["S12", "S13", "S14"],
      "rules": [
        "civil-code-2020第157条、第552条、第687条、第688条、第691条、第697条",
        "guarantee-2020第13条、第29条"
      ],
      "calculation": "乙应立即给付的剩余实体债务＝122828.00＋202317.84＋151539.07＋1403.29＋0.00＝478088.20元。",
      "explanation": "戊、庚各自的202317.84元责任均覆盖同一笔B余额，不是各承担一半，也不是在B之外增加两笔债权。己的一般保证覆盖同一C余额但目前不能立即请求；辛对其中76471.18元与乙承担连带债务，不增加C余额，也不减少己的原保证范围。任何主体实际清偿同一债务，其他主体就相应已清偿部分同步减责，甲不得重复受偿。全部实体债权总额为478088.20元，保证及债务加入金额均不得再加进乙的总额。"
    }
  }
